from six import with_metaclass
from abc import ABCMeta
from taf.internal.sw.dcap.rd.client.dcap_emil_decoder.v1.api.files_api import FilesApi
from taf.internal.sw.dcap.rd.client.dcap_emil_decoder.v1 import ApiClient, Configuration, ApiException
from taf.sw.dcap.rd.exception import IncorrectLoginCredentials
from taf.sw.dcap.rd.services.cm.cm_base import CM
import logging

from taf.sw.dcap.rd.log_request_response import log_request_response

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


def get_config_details(con_details):
    conf = Configuration()
    conf.verify_ssl = False
    conf.api_key_prefix['key'] = 'Bearer'
    conf.host = con_details.make_configuration_host(original_endpoint=conf.host)
    return conf


def create_filter_list(filter_list):
    operators = ['==', '!=', '<=', '>=', '=', '<', '>']
    result_list = []
    for user_input in filter_list:
        for operator in operators:
            if operator in user_input:
                key, value = (x.strip() for x in map(str, user_input.split(operator, 1)))
                result_list.append({'key': key, 'operator': operator, 'value': value})
                break
    if not result_list:
        logger.info("Invalid input format. Please use one of the supported comparison operators.")
    return result_list


class Decoderv1(with_metaclass(ABCMeta, object)):
    def __init__(self, con_details):
        con_details.base_url = '{protocol}{host}:{port}/emil-decoder'.format(protocol=con_details.protocol,
                                                                             host=con_details.host,
                                                                             port=con_details.port)
        conf = get_config_details(con_details)

        api_client = ApiClient(configuration=conf)
        api_client.request = log_request_response(api_client.request)
        self.api_client = FilesApi(api_client)

    def get_sacks(self, timeout):
        return self.api_client.api_files_v1_sacks_get(_request_timeout=timeout)

    def upload_sacks(self, file_name, timeout):
        return self.api_client.api_files_v1_sacks_post(data=file_name,
                                                       _request_timeout=timeout)

    def upload_encoded_file(self, file_name, profile, session_Id, username, timeout):
        return self.api_client.api_files_v1_post(data=file_name, profile=profile, session_id=session_Id,
                                                 username=username, _request_timeout=timeout)

    def get_encoded_files_info(self, timeout=None):
        return self.api_client.api_files_v1_get(_request_timeout=timeout)

    def get_decoded_file_contents(self, session_id, data_source_id, what, timeout, **kwargs):
        what = what if what else 'source'
        if 'filter' in kwargs and isinstance(kwargs['filter'], list):
            filtered_string = create_filter_list(kwargs.get('filter'))
            kwargs['filter'] = ','.join(['"{key}"{operator}"{value}"'.format(
                key=item['key'],
                operator=item['operator'],
                value=item['value']) for item in filtered_string])
        return self.api_client.api_files_v1_session_id_id_value_what_get(session_id=session_id,
                                                                         id_value=data_source_id,
                                                                         what=what,
                                                                         _request_timeout=timeout,
                                                                         **kwargs)

    def get_decoded_file_contents_in_json(self, session_id, data_source_id, what, timeout, **kwargs):
        return self.get_decoded_file_contents(session_id, data_source_id, what, timeout, **kwargs)

    def get_decoded_file_contents_in_csv(self, session_id, data_source_id, what, timeout, **kwargs):
        kwargs.update({'view': 'csv'})
        return self.get_decoded_file_contents(session_id, data_source_id, what, timeout, **kwargs)

    def get_decoding_profile_info(self, timeout):
        return self.api_client.api_files_v1_profiles_get(_request_timeout=timeout)

    def upload_decoding_profile(self, profile_name, profile_bases, profile_file_path, timeout):
        try:
            return self.api_client.api_files_v1_profiles_post(names=profile_name,
                                                              bases=profile_bases,
                                                              zip_file=profile_file_path,
                                                              _request_timeout=timeout)
        except ApiException as e:
            if e.status == 422:
                logger.debug("An ApiException occurred: %s", str(e))
                raise RuntimeError("The profile zip file provided is missing required parameters or has inconsistent"
                                   " data. Please check the file and try again.")
            elif e.status == 403:
                logger.debug("An ApiException occurred: %s", str(e))
                raise IncorrectLoginCredentials("The current user does not have permission to upload profiles to the"
                                                " json-server. Please connect the DCAP with a user that has the "
                                                "necessary permissions (e.g. 'nivuser') and try again.")

    def list_session_files(self, session_id, keepalive, timeout):
        return self.api_client.api_files_v1_session_id_get(session_id=session_id,
                                                           keepalive=keepalive,
                                                           _request_timeout=timeout)

    def download_session_file(self, session_id, file_name, target_dir, timeout=None):
        result_path = self.api_client.api_files_v1_session_id_file_name_file_get(session_id=session_id,
                                                                                 file_name=file_name,
                                                                                 _request_timeout=timeout)
        return CM.move_logs_to_target_dir(result_path=result_path, target_dir=target_dir)

    def delete_session_data(self, session_id, timeout):
        try:
            self.api_client.api_files_v1_session_id_delete(session_id=session_id,
                                                           _request_timeout=timeout)
            return "Success"
        except ApiException as e:
            if e.status == 404:
                raise RuntimeError("Specified session does not exist")
